package app.rwun;
import android.content.Context;import java.nio.file.Files;import java.time.LocalDate;import org.json.*;
/** Synthetic rules/storage regression; not physical audio or sensor acceptance. */
public final class VoiceCoachHostTest {
 static int count;
 static RunStore store()throws Exception{return new RunStore(new Context(Files.createTempDirectory("openrun-voice").toFile()));}
 static JSONObject reflection(int stage,boolean complete,Boolean manageable)throws Exception{JSONObject r=new JSONObject().put("stage",stage).put("complete",complete);if(manageable!=null)r.put("manageable",manageable);return r;}
 static RunStore.Run run(String id,int ago,int effort,int fatigue,boolean pain){return new RunStore.Run(id,LocalDate.now().minusDays(ago).toString(),3,24,effort,fatigue,pain,"GPS","",0,1440);}
 static void evidence(RunStore s)throws Exception{for(int i=0;i<3;i++)s.add(run("beginner:0:"+i,6-i*2,4,2,false),reflection(0,true,true));}
 static void check(boolean yes,String why){count++;if(!yes)throw new AssertionError(why);}
 static void reject(Runnable work,String why){boolean rejected=false;try{work.run();}catch(RuntimeException expected){rejected=true;}check(rejected,why);}
 public static void main(String[] args)throws Exception{
  RunStore s=store();check(CoachingMemory.settings(s).mode()==VoiceGuidance.Mode.STANDARD,"upgrade default");check(CoachingMemory.lesson(s).contains("baseline"),"missing data stays unknown");
  s.coachSettings(new VoiceGuidance.Settings(VoiceGuidance.Mode.DETAILED,180,false,170));check(CoachingMemory.settings(s).heartLimit()==170,"preferences persist");RunStore.validatePreferences(s.backupPreferences());
  JSONObject bad=s.backupPreferences(),feature=new JSONObject(bad.getString("v103"));feature.getJSONObject("coaching").getJSONObject("settings").put("interval",180.5);bad.put("v103",feature.toString());boolean invalid=false;try{RunStore.validatePreferences(bad);}catch(Exception expected){invalid=true;}check(invalid,"fractional interval rejected");
  reject(()->new VoiceGuidance.Settings(VoiceGuidance.Mode.STANDARD,30,true,0),"excessive cue frequency refused");reject(()->new VoiceGuidance.Settings(VoiceGuidance.Mode.STANDARD,300,true,80),"invalid enabled threshold refused");
  for(int i=0;i<BeginnerProgramme.count();i++){var def=BeginnerProgramme.workout(i);check(def.steps().stream().allMatch(st->st.metres()==0),"timed sessions invent no distance");check(def.steps().stream().mapToLong(WorkoutFactory.Step::seconds).sum()==BeginnerProgramme.totalSeconds(i),"briefing equals definition");WorkoutEngine e=new WorkoutEngine(def);long time=0;e.update(0,0,Double.NaN);for(var step:def.steps()){time+=step.seconds();e.update(time,0,Double.NaN);}check(e.complete(),"timed stages complete without GPS");if(i>0)check(BeginnerProgramme.totalSeconds(i)-600<=1.26*(BeginnerProgramme.totalSeconds(i-1)-600),"bounded main duration change");}
  var quiet=new VoiceGuidance.Settings(VoiceGuidance.Mode.QUIET,180,false,170);var guidance=new VoiceGuidance();check(guidance.update(1000,0,Long.MAX_VALUE,true,false,quiet).isEmpty(),"quiet suppresses optional prompts");check(guidance.update(1001,175,0,true,false,quiet).isEmpty(),"one high sample is insufficient");check(guidance.update(1032,175,11000,true,false,quiet).isEmpty(),"stale HR resets window");guidance.update(1033,175,0,true,false,quiet);for(int tick=1034;tick<1063;tick++)guidance.update(tick,175,0,true,false,quiet);check(guidance.update(1063,175,0,true,false,quiet).contains("chosen alert threshold"),"sustained fresh HR reminder");check(guidance.update(1065,175,0,true,false,quiet).isEmpty(),"HR cooldown");guidance.resetAfterPause(1200);check(guidance.update(1201,175,0,true,false,quiet).isEmpty(),"pause resets HR");var gap=new VoiceGuidance();gap.update(0,175,0,true,false,quiet);check(gap.update(60,175,0,true,false,quiet).isEmpty(),"unobserved time is not continuous evidence");check(new VoiceGuidance().update(300,180,0,true,false,VoiceGuidance.Settings.defaults()).startsWith("Effort check"),"no guessed HR zone");check(new VoiceGuidance().update(300,180,0,false,false,VoiceGuidance.Settings.defaults()).isEmpty(),"no easy-effort nag in recovery/quality steps");
  var q=new SpeechQueue();q.offer(new SpeechQueue.Cue("pace","Old pace",SpeechQueue.Kind.PACE,1,0,100),0,1);q.offer(new SpeechQueue.Cue("phase","Walk now",SpeechQueue.Kind.PHASE,2,1,100),1,2);check(q.size()==1&&q.poll(2,2).text().equals("Walk now"),"phase removes obsolete advice");q.offer(new SpeechQueue.Cue("split","Split",SpeechQueue.Kind.SPLIT,2,0,10),0,2);check(q.poll(11,2)==null,"expired cue not replayed");for(int i=0;i<20;i++)q.offer(new SpeechQueue.Cue("same","Repeat",SpeechQueue.Kind.EFFORT,2,0,100),0,2);check(q.size()==1,"duplicates coalesced");q.clear();check(q.size()==0,"interruption clears queue");
  RunStore plan=store();evidence(plan);String before=CoachingMemory.fingerprint(plan);check(CoachingMemory.progressionReason(plan,1).contains("separate days"),"evidence explained");check(plan.latestCoachChange()==null,"preview has no history");plan.changeCoachStage(before,1);check(CoachingMemory.stage(plan)==1&&plan.runs().size()==3,"apply preserves history");JSONObject change=plan.latestCoachChange();plan.undoCoachStage(change.getString("id"));check(CoachingMemory.stage(plan)==0&&plan.latestCoachChange().getString("kind").equals("UNDO"),"undo creates new event");reject(()->plan.undoCoachStage(change.optString("id")),"undo is not repeatable");plan.changeCoachStage(CoachingMemory.fingerprint(plan),1);String latest=plan.latestCoachChange().getString("id");plan.add(run("newer",0,5,2,false),reflection(-1,false,true));reject(()->plan.undoCoachStage(latest),"newer work preserved");
  RunStore stale=store();evidence(stale);String preview=CoachingMemory.fingerprint(stale);stale.coachCheckin(4,false);reject(()->stale.changeCoachStage(preview,1),"stale preview refused");reject(()->stale.changeCoachStage(CoachingMemory.fingerprint(stale),1),"high fatigue blocks progression");RunStore pain=store();evidence(pain);pain.changeCoachStage(CoachingMemory.fingerprint(pain),1);String changeId=pain.latestCoachChange().getString("id");pain.coachCheckin(2,true);reject(()->pain.undoCoachStage(changeId),"undo refuses hold");check(pain.resting(),"hold retained");
  RunStore hard=store();evidence(hard);hard.add(run("hard",0,9,4,false),reflection(0,false,false));reject(()->hard.changeCoachStage(CoachingMemory.fingerprint(hard),1),"no cherry-picking old successes");RunStore unknown=store();for(int i=0;i<3;i++)unknown.add(run("unknown"+i,6-i*2,4,2,false),reflection(0,true,null));reject(()->unknown.changeCoachStage(CoachingMemory.fingerprint(unknown),1),"unknown manageability cannot establish readiness");
  RunStore removed=store();evidence(removed);removed.softDelete("beginner:0:2");check(CoachingMemory.stageEvidence(removed).size()==2,"deleted evidence excluded");removed.undoDelete();check(CoachingMemory.stageEvidence(removed).size()==3,"restored evidence available");removed.correctTotals("beginner:0:2",2,1200);check(CoachingMemory.stageEvidence(removed).size()<3,"correction invalidates completion receipt");
  RunStore interrupted=store();interrupted.checkpoint(new JSONObject().put("id","beginner:0:recover").put("coachStage",0).put("workoutComplete",true).toString());interrupted.add(run("beginner:0:recover",0,4,2,true),interrupted.recordingReview("beginner:0:recover",true,null));check(interrupted.resting()&&CoachingMemory.entries(interrupted).get(0).stage()==0,"recovered receipt and hold saved together");
  RunStore imported=store();var raw=new RunStore.Run("health:review",LocalDate.now().toString(),5,40,5,2,false,"Health Connect · sample","",0,2400);imported.importActivity(raw,false,RunStore.origin("sample","review",1000,2401000));check(CoachingMemory.entries(imported).isEmpty(),"imported effort is not inferred");String receipt=CoachingMemory.hash(imported.runs().get(0).toString());imported.reviewRun(raw.sessionId(),receipt,4,2,true,true,null);check(imported.resting()&&imported.runs().get(0).km()==5&&CoachingMemory.entries(imported).get(0).stage()==-1,"explicit imported feedback preserves totals and invents no stage");reject(()->imported.reviewRun(raw.sessionId(),receipt,4,2,false,true,null),"stale reflection cannot overwrite feedback");imported.reviewRun(raw.sessionId(),CoachingMemory.hash(imported.runs().get(0).toString()),4,2,false,true,null);check(imported.resting(),"editing feedback never clears hold");
  RunStore sameDay=store();for(int i=0;i<3;i++)sameDay.add(run("same-day"+i,0,4,2,false),reflection(0,true,true));reject(()->sameDay.changeCoachStage(CoachingMemory.fingerprint(sameDay),1),"one day cannot supply three training days");System.out.println("Voice coach regressions passed: "+count+" assertions.");
 }
}
